package au.edu.uow.csci318.activity.exception;import au.edu.uow.csci318.activity.application.StudyActivityApplicationService.DependencyException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler{record ErrorBody(Instant timestamp,int status,String error,String message,String path,Map<String,String>validationErrors){}@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class})ResponseEntity<ErrorBody>bad(RuntimeException e,HttpServletRequest r){return make(HttpStatus.BAD_REQUEST,e,r);}@ExceptionHandler(NoSuchElementException.class)ResponseEntity<ErrorBody>missing(RuntimeException e,HttpServletRequest r){return make(HttpStatus.NOT_FOUND,e,r);}@ExceptionHandler(DependencyException.class)ResponseEntity<ErrorBody>unavailable(RuntimeException e,HttpServletRequest r){return make(HttpStatus.SERVICE_UNAVAILABLE,e,r);}private ResponseEntity<ErrorBody>make(HttpStatus s,RuntimeException e,HttpServletRequest r){return ResponseEntity.status(s).body(new ErrorBody(Instant.now(),s.value(),s.getReasonPhrase(),e.getMessage(),r.getRequestURI(),null));}}
